		pixels: selected.length,
		meanLuma: Number((sum / selected.length).toFixed(6)),
		p50Luma: Number(selected[p50Index].toFixed(6)),
		p90Luma: Number(selected[p90Index].toFixed(6)),
		maxLuma: Number(maxValue.toFixed(6))
