		width: width,
		height: height,
		finitePixels: finitePixels,
		nonFinitePixels: nonFinitePixels,
		meanRgb: finitePixels ? [r / finitePixels, g / finitePixels, b / finitePixels] : [0, 0, 0],
		meanLuma: finitePixels ? sumLuma / finitePixels : 0,
